1011→// ensureSessionsBranch ensures the entire/checkpoints/v1 branch exists.
1012→func (s *GitStore) ensureSessionsBranch() error {
1013→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1014→	_, err := s.repo.Reference(refName, true)
1015→	if err == nil {
1016→		return nil // Branch exists
1017→	}
1018→
1019→	// Create orphan branch with empty tree
1020→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
1021→	if err != nil {
1022→		return err
1023→	}
1024→
1025→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
1026→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
1027→	if err != nil {
1028→		return err
1029→	}
1030→
1031→	newRef := plumbing.NewHashReference(refName, commitHash)
1032→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1033→		return fmt.Errorf("failed to set branch reference: %w", err)
1034→	}
1035→	return nil
1036→}
