  35→// errStop is a sentinel error used to break out of git log iteration.
  36→// Shared across strategies that iterate through git commits.
  37→// NOTE: A similar sentinel exists in checkpoint/temporary.go - this is intentional.
  38→// Each package needs its own package-scoped sentinel for git log iteration patterns.
  39→var errStop = errors.New("stop iteration")
  40→
  41→// IsEmptyRepository returns true if the repository has no commits yet.
  42→// After git-init, HEAD points to an unborn branch (e.g., refs/heads/main)
  43→// whose target does not yet exist. repo.Head() returns ErrReferenceNotFound
  44→// in this case.
  45→func IsEmptyRepository(repo *git.Repository) bool {
  46→	_, err := repo.Head()
  47→	return errors.Is(err, plumbing.ErrReferenceNotFound)
  48→}
  49→
  50→// IsAncestorOf checks if commit is an ancestor of (or equal to) target.
  51→// Returns true if target can reach commit by following parent links.
  52→// Limits search to 1000 commits to avoid excessive traversal.
  53→func IsAncestorOf(repo *git.Repository, commit, target plumbing.Hash) bool {
  54→	if commit == target {
  55→		return true
  56→	}
  57→
  58→	iter, err := repo.Log(&git.LogOptions{From: target})
  59→	if err != nil {
  60→		return false
  61→	}
  62→	defer iter.Close()
  63→
  64→	found := false
  65→	count := 0
  66→	_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
  67→		count++
  68→		if count > 1000 {
  69→			return errStop
  70→		}
  71→		if c.Hash == commit {
  72→			found = true
  73→			return errStop
  74→		}
  75→		return nil
  76→	})
  77→
  78→	return found
  79→}
