  81→// ListCheckpoints returns all checkpoints from the entire/checkpoints/v1 branch.
  82→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
  83→// Used by both manual-commit and auto-commit strategies.
  84→func ListCheckpoints() ([]CheckpointInfo, error) {
  85→	repo, err := OpenRepository()
  86→	if err != nil {
  87→		return nil, fmt.Errorf("failed to open git repository: %w", err)
  88→	}
  89→
  90→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  91→	ref, err := repo.Reference(refName, true)
  92→	if err != nil {
  93→		//nolint:nilerr // No sessions branch yet is expected, return empty list
  94→		return []CheckpointInfo{}, nil
  95→	}
  96→
  97→	commit, err := repo.CommitObject(ref.Hash())
  98→	if err != nil {
  99→		return nil, fmt.Errorf("failed to get commit object: %w", err)
 100→	}
 101→
 102→	tree, err := commit.Tree()
 103→	if err != nil {
 104→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
 105→	}
 106→
 107→	var checkpoints []CheckpointInfo
 108→
 109→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
 110→	// The tree has 2-character directories (hex buckets)
 111→	for _, bucketEntry := range tree.Entries {
 112→		if bucketEntry.Mode != filemode.Dir {
 113→			continue
 114→		}
 115→		// Bucket should be 2 hex chars
 116→		if len(bucketEntry.Name) != 2 {
 117→			continue
 118→		}
 119→
 120→		bucketTree, treeErr := repo.TreeObject(bucketEntry.Hash)
 121→		if treeErr != nil {
 122→			continue
 123→		}
 124→
 125→		// Each entry in the bucket is the remaining part of the checkpoint ID
 126→		for _, checkpointEntry := range bucketTree.Entries {
 127→			if checkpointEntry.Mode != filemode.Dir {
 128→				continue
 129→			}
 130→
 131→			checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
 132→			if cpTreeErr != nil {
 133→				continue
 134→			}
 135→
 136→			// Reconstruct checkpoint ID: <bucket><remaining>
 137→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
 138→			checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
 139→			if cpErr != nil {
 140→				// Skip invalid checkpoint IDs
 141→				continue
 142→			}
 143→
 144→			info := CheckpointInfo{
 145→				CheckpointID: checkpointID,
 146→			}
 147→
 148→			// Get details from metadata file (CheckpointSummary format)
 149→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
 150→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
 151→					var summary checkpoint.CheckpointSummary
 152→					if json.Unmarshal([]byte(content), &summary) == nil && len(summary.Sessions) > 0 {
 153→						info.CheckpointsCount = summary.CheckpointsCount
 154→						info.FilesTouched = summary.FilesTouched
 155→						info.SessionCount = len(summary.Sessions)
 156→
 157→						// Read session-level metadata for Agent, SessionID, CreatedAt, SessionIDs
 158→						for i, sessionPaths := range summary.Sessions {
 159→							if sessionPaths.Metadata != "" {
 160→								// SessionFilePaths now contains absolute paths with leading "/"
 161→								// Strip the leading "/" for tree.File() which expects paths without leading slash
 162→								sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
 163→								if sessionFile, sErr := tree.File(sessionMetadataPath); sErr == nil {
 164→									if sessionContent, scErr := sessionFile.Contents(); scErr == nil {
 165→										var sessionMetadata checkpoint.CommittedMetadata
 166→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
 167→											info.SessionIDs = append(info.SessionIDs, sessionMetadata.SessionID)
 168→											// Use first session's metadata for Agent, SessionID, CreatedAt
 169→											if i == 0 {
 170→												info.Agent = sessionMetadata.Agent
 171→												info.SessionID = sessionMetadata.SessionID
 172→												info.CreatedAt = sessionMetadata.CreatedAt
 173→												info.IsTask = sessionMetadata.IsTask
 174→												info.ToolUseID = sessionMetadata.ToolUseID
 175→											}
 176→										}
 177→									}
 178→								}
 179→							}
 180→						}
 181→					}
 182→				}
 183→			}
 184→
 185→			checkpoints = append(checkpoints, info)
 186→		}
 187→	}
 188→
 189→	// Sort by time (most recent first)
 190→	sort.Slice(checkpoints, func(i, j int) bool {
 191→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
 192→	})
 193→
 194→	return checkpoints, nil
 195→}
