 207→// isProtectedPath returns true if relPath is inside a directory that should
 208→// never be modified or deleted during rewind or other destructive operations.
 209→// Protected directories include git internals, entire metadata, and all
 210→// registered agent config directories.
 211→func isProtectedPath(relPath string) bool {
 212→	for _, dir := range protectedDirs() {
 213→		if relPath == dir || strings.HasPrefix(relPath, dir+string(filepath.Separator)) {
 214→			return true
 215→		}
 216→	}
 217→	return false
 218→}
