 278→// ensureMetadataBranch creates the orphan entire/checkpoints/v1 branch if it doesn't exist.
 279→// This branch has no parent and starts with an empty tree.
 280→func EnsureMetadataBranch(repo *git.Repository) error {
 281→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
 282→
 283→	// Check if branch already exists
 284→	_, err := repo.Reference(refName, true)
 285→	if err == nil {
 286→		// Branch already exists
 287→		return nil
 288→	}
 289→
 290→	// Create empty tree (no files)
 291→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
 292→	obj := repo.Storer.NewEncodedObject()
 293→	if err := emptyTree.Encode(obj); err != nil {
 294→		return fmt.Errorf("failed to encode empty tree: %w", err)
 295→	}
 296→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
 297→	if err != nil {
 298→		return fmt.Errorf("failed to store empty tree: %w", err)
 299→	}
 300→
 301→	// Create orphan commit (no parent)
 302→	now := time.Now()
 303→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
 304→	sig := object.Signature{
 305→		Name:  authorName,
 306→		Email: authorEmail,
 307→		When:  now,
 308→	}
 309→
 310→	commit := &object.Commit{
 311→		TreeHash:  emptyTreeHash,
 312→		Author:    sig,
 313→		Committer: sig,
 314→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata for the auto-commit strategy.\n",
 315→	}
 316→	// Note: No ParentHashes - this is an orphan commit
 317→
 318→	commitObj := repo.Storer.NewEncodedObject()
 319→	if err := commit.Encode(commitObj); err != nil {
 320→		return fmt.Errorf("failed to encode orphan commit: %w", err)
 321→	}
 322→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
 323→	if err != nil {
 324→		return fmt.Errorf("failed to store orphan commit: %w", err)
 325→	}
 326→
 327→	// Create branch reference
 328→	ref := plumbing.NewHashReference(refName, commitHash)
 329→	if err := repo.Storer.SetReference(ref); err != nil {
 330→		return fmt.Errorf("failed to create metadata branch: %w", err)
 331→	}
 332→
 333→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
 334→	return nil
 335→}
