 337→// readCheckpointMetadata reads metadata.json from a checkpoint path on entire/checkpoints/v1.
 338→// With the new format, root metadata.json is a CheckpointSummary with Agents array.
 339→// This function reads the summary and extracts relevant fields into CheckpointInfo,
 340→// also reading session-level metadata for IsTask/ToolUseID fields.
 341→func ReadCheckpointMetadata(tree *object.Tree, checkpointPath string) (*CheckpointInfo, error) {
 342→	metadataPath := checkpointPath + "/metadata.json"
 343→	file, err := tree.File(metadataPath)
 344→	if err != nil {
 345→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
 346→	}
 347→
 348→	content, err := file.Contents()
 349→	if err != nil {
 350→		return nil, fmt.Errorf("failed to read metadata: %w", err)
 351→	}
 352→
 353→	// Try to parse as CheckpointSummary first (new format)
 354→	var summary checkpoint.CheckpointSummary
 355→	if err := json.Unmarshal([]byte(content), &summary); err == nil {
 356→		// If we have sessions array, this is the new format
 357→		if len(summary.Sessions) > 0 {
 358→			info := &CheckpointInfo{
 359→				CheckpointID:     summary.CheckpointID,
 360→				CheckpointsCount: summary.CheckpointsCount,
 361→				FilesTouched:     summary.FilesTouched,
 362→				SessionCount:     len(summary.Sessions),
 363→			}
 364→
 365→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
 366→			var sessionIDs []string
 367→			for i, sessionPaths := range summary.Sessions {
 368→				if sessionPaths.Metadata != "" {
 369→					// SessionFilePaths now contains absolute paths with leading "/"
 370→					// Strip the leading "/" for tree.File() which expects paths without leading slash
 371→					sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
 372→					if sessionFile, err := tree.File(sessionMetadataPath); err == nil {
 373→						if sessionContent, err := sessionFile.Contents(); err == nil {
 374→							var sessionMetadata checkpoint.CommittedMetadata
 375→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
 376→								sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
 377→								// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
 378→								if i == 0 {
 379→									info.Agent = sessionMetadata.Agent
 380→									info.SessionID = sessionMetadata.SessionID
 381→									info.CreatedAt = sessionMetadata.CreatedAt
 382→									info.IsTask = sessionMetadata.IsTask
 383→									info.ToolUseID = sessionMetadata.ToolUseID
 384→								}
 385→							}
 386→						}
 387→					}
 388→				}
 389→			}
 390→			info.SessionIDs = sessionIDs
 391→
 392→			return info, nil
 393→		}
 394→	}
 395→
 396→	// Fall back to parsing as CheckpointInfo (old format or direct info)
 397→	var metadata CheckpointInfo
 398→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
 399→		return nil, fmt.Errorf("failed to parse metadata: %w", err)
 400→	}
 401→
 402→	return &metadata, nil
 403→}
