 471→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
 472→func isOnlySeparators(s string) bool {
 473→	for _, r := range s {
 474→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
 475→			return false
 476→		}
 477→	}
 478→	return true
 479→}
