 481→// ReadAllSessionPromptsFromTree reads the first prompt for all sessions in a multi-session checkpoint.
 482→// Returns a slice of prompts parallel to sessionIDs (oldest to newest).
 483→// For single-session checkpoints, returns a slice with just the root prompt.
 484→func ReadAllSessionPromptsFromTree(tree *object.Tree, checkpointPath string, sessionCount int, sessionIDs []string) []string {
 485→	if sessionCount <= 1 || len(sessionIDs) <= 1 {
 486→		// Single session - just return the root prompt
 487→		prompt := ReadSessionPromptFromTree(tree, checkpointPath)
 488→		if prompt != "" {
 489→			return []string{prompt}
 490→		}
 491→		return nil
 492→	}
 493→
 494→	// Multi-session: read prompts from archived folders (0/, 1/, etc.) and root
 495→	prompts := make([]string, len(sessionIDs))
 496→
 497→	// Read archived session prompts (folders 0, 1, ... N-2)
 498→	for i := range sessionCount - 1 {
 499→		archivedPath := fmt.Sprintf("%s/%d", checkpointPath, i)
 500→		prompts[i] = ReadSessionPromptFromTree(tree, archivedPath)
 501→	}
 502→
 503→	// Read the most recent session prompt (at root level)
 504→	prompts[len(prompts)-1] = ReadSessionPromptFromTree(tree, checkpointPath)
 505→
 506→	return prompts
 507→}
