 554→// OpenRepository opens the git repository with linked worktree support enabled.
 555→// It uses git.PlainOpenWithOptions with EnableDotGitCommonDir set to true,
 556→// which is required for proper operation in git worktrees created via 'git worktree add'.
 557→//
 558→// Without EnableDotGitCommonDir, go-git operations in worktrees can silently fail:
 559→// - Commits appear to succeed but are not persisted
 560→// - Refs are written to incorrect locations
 561→// - The worktree's HEAD/index don't get updated properly
 562→//
 563→// This happens because worktrees use .git as a file (pointing to the main repo)
 564→// rather than a directory, and go-git needs to route paths correctly between
 565→// shared (.git/) and per-worktree (.git/worktrees/<name>/) locations.
 566→//
 567→// The function first uses 'git rev-parse --show-toplevel' to find the repository
 568→// root, which works correctly even when called from a subdirectory within the repo.
 569→func OpenRepository() (*git.Repository, error) {
 570→	// First, find the repository root using git rev-parse --show-toplevel
 571→	// This works correctly from any subdirectory within the repository
 572→	repoRoot, err := GetWorktreePath()
 573→	if err != nil {
 574→		// Fallback to current directory if git command fails
 575→		// (e.g., if git is not installed or we're not in a repo)
 576→		repoRoot = "."
 577→	}
 578→
 579→	repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{
 580→		EnableDotGitCommonDir: true,
 581→	})
 582→	if err != nil {
 583→		return nil, fmt.Errorf("failed to open repository: %w", err)
 584→	}
 585→	return repo, nil
 586→}
 587→
 588→// IsInsideWorktree returns true if the current directory is inside a git worktree
 589→// (as opposed to the main repository). Worktrees have .git as a file pointing
 590→// to the main repo, while the main repo has .git as a directory.
 591→// This function works correctly from any subdirectory within the repository.
 592→func IsInsideWorktree() bool {
 593→	// First find the repository root
 594→	repoRoot, err := GetWorktreePath()
 595→	if err != nil {
 596→		return false
 597→	}
 598→
 599→	gitPath := filepath.Join(repoRoot, gitDir)
 600→	gitInfo, err := os.Stat(gitPath)
 601→	if err != nil {
 602→		return false
 603→	}
 604→	return !gitInfo.IsDir()
 605→}
 606→
 607→// GetMainRepoRoot returns the root directory of the main repository.
 608→// In the main repo, this is the worktree path (repo root).
 609→// In a worktree, this parses the .git file to find the main repo.
 610→// This function works correctly from any subdirectory within the repository.
 611→//
 612→// Per gitrepository-layout(5), a worktree's .git file is a "gitfile" containing
 613→// "gitdir: <path>" pointing to $GIT_DIR/worktrees/<id> in the main repository.
 614→// See: https://git-scm.com/docs/gitrepository-layout
 615→func GetMainRepoRoot() (string, error) {
 616→	// First find the worktree/repo root
 617→	repoRoot, err := GetWorktreePath()
 618→	if err != nil {
 619→		return "", fmt.Errorf("failed to get worktree path: %w", err)
 620→	}
 621→
 622→	if !IsInsideWorktree() {
 623→		return repoRoot, nil
 624→	}
 625→
 626→	// Worktree .git file contains: "gitdir: /path/to/main/.git/worktrees/<id>"
 627→	gitFilePath := filepath.Join(repoRoot, gitDir)
 628→	content, err := os.ReadFile(gitFilePath) //nolint:gosec // G304: gitFilePath is constructed from repo root, not user input
 629→	if err != nil {
 630→		return "", fmt.Errorf("failed to read .git file: %w", err)
 631→	}
 632→
 633→	gitdir := strings.TrimSpace(string(content))
 634→	gitdir = strings.TrimPrefix(gitdir, "gitdir: ")
 635→
 636→	// Extract main repo root: everything before "/.git/"
 637→	idx := strings.LastIndex(gitdir, "/.git/")
 638→	if idx < 0 {
 639→		return "", fmt.Errorf("unexpected gitdir format: %s", gitdir)
 640→	}
 641→	return gitdir[:idx], nil
 642→}
 643→
 644→// GetGitCommonDir returns the path to the shared git directory.
 645→// In a regular checkout, this is .git/
 646→// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
 647→// Uses git rev-parse --git-common-dir for reliable handling of worktrees.
 648→func GetGitCommonDir() (string, error) {
 649→	ctx := context.Background()
 650→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
 651→	cmd.Dir = "."
 652→	output, err := cmd.Output()
 653→	if err != nil {
 654→		return "", fmt.Errorf("failed to get git common dir: %w", err)
 655→	}
 656→
 657→	commonDir := strings.TrimSpace(string(output))
 658→
 659→	// git rev-parse --git-common-dir returns relative paths from the working directory,
 660→	// so we need to make it absolute if it isn't already
 661→	if !filepath.IsAbs(commonDir) {
 662→		commonDir = filepath.Join(".", commonDir)
 663→	}
 664→
 665→	return filepath.Clean(commonDir), nil
 666→}
