 668→// GetWorktreePath returns the absolute path to the current worktree root.
 669→// This is the working directory path, not the git directory.
 670→func GetWorktreePath() (string, error) {
 671→	ctx := context.Background()
 672→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
 673→	output, err := cmd.Output()
 674→	if err != nil {
 675→		return "", fmt.Errorf("failed to get worktree path: %w", err)
 676→	}
 677→	return strings.TrimSpace(string(output)), nil
 678→}
