 680→// EnsureEntireGitignore ensures all required entries are in .entire/.gitignore
 681→// Works correctly from any subdirectory within the repository.
 682→func EnsureEntireGitignore() error {
 683→	// Get absolute path for the gitignore file
 684→	gitignoreAbs, err := paths.AbsPath(entireGitignore)
 685→	if err != nil {
 686→		gitignoreAbs = entireGitignore // Fallback to relative
 687→	}
 688→
 689→	// Read existing content
 690→	var content string
 691→	if data, err := os.ReadFile(gitignoreAbs); err == nil { //nolint:gosec // path is from AbsPath or constant
 692→		content = string(data)
 693→	}
 694→
 695→	// All entries that should be in .entire/.gitignore
 696→	requiredEntries := []string{
 697→		"tmp/",
 698→		"settings.local.json",
 699→		"metadata/",
 700→		"logs/",
 701→	}
 702→
 703→	// Track what needs to be added
 704→	var toAdd []string
 705→	for _, entry := range requiredEntries {
 706→		if !strings.Contains(content, entry) {
 707→			toAdd = append(toAdd, entry)
 708→		}
 709→	}
 710→
 711→	// Nothing to add
 712→	if len(toAdd) == 0 {
 713→		return nil
 714→	}
 715→
 716→	// Ensure .entire directory exists
 717→	if err := os.MkdirAll(filepath.Dir(gitignoreAbs), 0o750); err != nil {
 718→		return fmt.Errorf("failed to create .entire directory: %w", err)
 719→	}
 720→
 721→	// Append missing entries to gitignore
 722→	var sb strings.Builder
 723→	for _, entry := range toAdd {
 724→		sb.WriteString(entry + "\n")
 725→	}
 726→	content += sb.String()
 727→
 728→	if err := os.WriteFile(gitignoreAbs, []byte(content), 0o644); err != nil { //nolint:gosec // path is from AbsPath or constant
 729→		return fmt.Errorf("failed to write gitignore: %w", err)
 730→	}
 731→	return nil
 732→}
