 734→// checkCanRewind checks if working directory is clean enough for rewind.
 735→// Returns (canRewind, reason, error). Shared by shadow and linear-shadow strategies.
 736→func checkCanRewind() (bool, string, error) {
 737→	repo, err := OpenRepository()
 738→	if err != nil {
 739→		return false, "", fmt.Errorf("failed to open git repository: %w", err)
 740→	}
 741→
 742→	worktree, err := repo.Worktree()
 743→	if err != nil {
 744→		return false, "", fmt.Errorf("failed to get worktree: %w", err)
 745→	}
 746→
 747→	status, err := worktree.Status()
 748→	if err != nil {
 749→		return false, "", fmt.Errorf("failed to get status: %w", err)
 750→	}
 751→
 752→	if status.IsClean() {
 753→		return true, "", nil
 754→	}
 755→
 756→	var modified, added, deleted []string
 757→	for file, st := range status {
 758→		// Skip .entire directory
 759→		if paths.IsInfrastructurePath(file) {
 760→			continue
 761→		}
 762→
 763→		// Skip untracked files
 764→		if st.Worktree == git.Untracked {
 765→			continue
 766→		}
 767→
 768→		switch {
 769→		case st.Staging == git.Added || st.Worktree == git.Added:
 770→			added = append(added, file)
 771→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
 772→			deleted = append(deleted, file)
 773→		case st.Staging == git.Modified || st.Worktree == git.Modified:
 774→			modified = append(modified, file)
 775→		}
 776→	}
 777→
 778→	if len(modified) == 0 && len(added) == 0 && len(deleted) == 0 {
 779→		return true, "", nil
 780→	}
 781→
 782→	var msg strings.Builder
 783→	msg.WriteString("You have uncommitted changes:\n")
 784→	for _, f := range modified {
 785→		msg.WriteString(fmt.Sprintf("  modified:   %s\n", f))
 786→	}
 787→	for _, f := range added {
 788→		msg.WriteString(fmt.Sprintf("  added:      %s\n", f))
 789→	}
 790→	for _, f := range deleted {
 791→		msg.WriteString(fmt.Sprintf("  deleted:    %s\n", f))
 792→	}
 793→	msg.WriteString("\nPlease commit or stash your changes before rewinding.")
 794→
 795→	return false, msg.String(), nil
 796→}
 797→
 798→// checkCanRewindWithWarning checks working directory and returns a warning with diff stats.
 799→// Unlike checkCanRewind, this always returns canRewind=true but includes a warning message
 800→// with +/- line stats for uncommitted changes. Used by manual-commit strategy.
 801→func checkCanRewindWithWarning() (bool, string, error) {
 802→	repo, err := OpenRepository()
 803→	if err != nil {
 804→		// Can't open repo - still allow rewind but without stats
 805→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo can't be opened
 806→	}
 807→
 808→	worktree, err := repo.Worktree()
 809→	if err != nil {
 810→		return true, "", nil //nolint:nilerr // Rewind allowed even if worktree can't be accessed
 811→	}
 812→
 813→	status, err := worktree.Status()
 814→	if err != nil {
 815→		return true, "", nil //nolint:nilerr // Rewind allowed even if status can't be retrieved
 816→	}
 817→
 818→	if status.IsClean() {
 819→		return true, "", nil
 820→	}
 821→
 822→	// Get HEAD commit tree for comparison - if we can't get it, just return without stats
 823→	head, err := repo.Head()
 824→	if err != nil {
 825→		return true, "", nil //nolint:nilerr // Rewind allowed even without HEAD (e.g., empty repo)
 826→	}
 827→
 828→	headCommit, err := repo.CommitObject(head.Hash())
 829→	if err != nil {
 830→		return true, "", nil //nolint:nilerr // Rewind allowed even if commit lookup fails
 831→	}
 832→
 833→	headTree, err := headCommit.Tree()
 834→	if err != nil {
 835→		return true, "", nil //nolint:nilerr // Rewind allowed even if tree lookup fails
 836→	}
 837→
 838→	type fileChange struct {
 839→		status   string // "modified", "added", "deleted"
 840→		added    int
 841→		removed  int
 842→		filename string
 843→	}
 844→
 845→	var changes []fileChange
 846→	// Use repo root, not cwd - git status returns paths relative to repo root
 847→	repoRoot, err := GetWorktreePath()
 848→	if err != nil {
 849→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo root lookup fails
 850→	}
 851→
 852→	for file, st := range status {
 853→		// Skip .entire directory
 854→		if paths.IsInfrastructurePath(file) {
 855→			continue
 856→		}
 857→
 858→		// Skip untracked files
 859→		if st.Worktree == git.Untracked {
 860→			continue
 861→		}
 862→
 863→		var change fileChange
 864→		change.filename = file
 865→
 866→		switch {
 867→		case st.Staging == git.Added || st.Worktree == git.Added:
 868→			change.status = "added"
 869→			// New file - count all lines as added
 870→			absPath := filepath.Join(repoRoot, file)
 871→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
 872→				change.added = countLines(content)
 873→			}
 874→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
 875→			change.status = "deleted"
 876→			// Deleted file - count lines from HEAD as removed
 877→			if entry, err := headTree.File(file); err == nil {
 878→				if content, err := entry.Contents(); err == nil {
 879→					change.removed = countLines([]byte(content))
 880→				}
 881→			}
 882→		case st.Staging == git.Modified || st.Worktree == git.Modified:
 883→			change.status = "modified"
 884→			// Modified file - compute diff stats
 885→			var headContent, workContent []byte
 886→			if entry, err := headTree.File(file); err == nil {
 887→				if content, err := entry.Contents(); err == nil {
 888→					headContent = []byte(content)
 889→				}
 890→			}
 891→			absPath := filepath.Join(repoRoot, file)
 892→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
 893→				workContent = content
 894→			}
 895→			if headContent != nil && workContent != nil {
 896→				change.added, change.removed = computeDiffStats(headContent, workContent)
 897→			}
 898→		default:
 899→			continue
 900→		}
 901→
 902→		changes = append(changes, change)
 903→	}
 904→
 905→	if len(changes) == 0 {
 906→		return true, "", nil
 907→	}
 908→
 909→	// Sort changes by filename for consistent output
 910→	sort.Slice(changes, func(i, j int) bool {
 911→		return changes[i].filename < changes[j].filename
 912→	})
 913→
 914→	var msg strings.Builder
 915→	msg.WriteString("The following uncommitted changes will be reverted:\n")
 916→
 917→	totalAdded, totalRemoved := 0, 0
 918→	for _, c := range changes {
 919→		totalAdded += c.added
 920→		totalRemoved += c.removed
 921→
 922→		var stats string
 923→		switch {
 924→		case c.added > 0 && c.removed > 0:
 925→			stats = fmt.Sprintf("+%d/-%d", c.added, c.removed)
 926→		case c.added > 0:
 927→			stats = fmt.Sprintf("+%d", c.added)
 928→		case c.removed > 0:
 929→			stats = fmt.Sprintf("-%d", c.removed)
 930→		}
 931→
 932→		msg.WriteString(fmt.Sprintf("  %-10s %s", c.status+":", c.filename))
 933→		if stats != "" {
 934→			msg.WriteString(fmt.Sprintf(" (%s)", stats))
 935→		}
 936→		msg.WriteString("\n")
 937→	}
 938→
 939→	if totalAdded > 0 || totalRemoved > 0 {
 940→		msg.WriteString(fmt.Sprintf("\nTotal: +%d/-%d lines\n", totalAdded, totalRemoved))
 941→	}
 942→
 943→	return true, msg.String(), nil
 944→}
