 946→// countLines counts the number of lines in content.
 947→func countLines(content []byte) int {
 948→	if len(content) == 0 {
 949→		return 0
 950→	}
 951→	count := 1
 952→	for _, b := range content {
 953→		if b == '\n' {
 954→			count++
 955→		}
 956→	}
 957→	// Don't count trailing newline as extra line
 958→	if len(content) > 0 && content[len(content)-1] == '\n' {
 959→		count--
 960→	}
 961→	return count
 962→}
 963→
 964→// computeDiffStats computes added and removed line counts between old and new content.
 965→// Uses a simple line-based diff algorithm.
 966→func computeDiffStats(oldContent, newContent []byte) (added, removed int) {
 967→	oldLines := splitLines(oldContent)
 968→	newLines := splitLines(newContent)
 969→
 970→	// Build a set of old lines with counts
 971→	oldSet := make(map[string]int)
 972→	for _, line := range oldLines {
 973→		oldSet[line]++
 974→	}
 975→
 976→	// Check which new lines are truly new
 977→	for _, line := range newLines {
 978→		if oldSet[line] > 0 {
 979→			oldSet[line]--
 980→		} else {
 981→			added++
 982→		}
 983→	}
 984→
 985→	// Remaining old lines are removed
 986→	for _, count := range oldSet {
 987→		removed += count
 988→	}
 989→
 990→	return added, removed
 991→}
 992→
 993→// splitLines splits content into lines, preserving empty lines.
 994→func splitLines(content []byte) []string {
 995→	if len(content) == 0 {
 996→		return nil
 997→	}
 998→	s := string(content)
 999→	// Remove trailing newline to avoid empty last element
1000→	s = strings.TrimSuffix(s, "\n")
1001→	return strings.Split(s, "\n")
1002→}
