1020→// StageFiles stages modified, new, and deleted files to the git worktree.
1021→//
1022→// This function handles three categories of file changes:
1023→//  1. Modified files: existing files that have been changed
1024→//  2. New files: files that were created during the session
1025→//  3. Deleted files: files that were removed during the session
1026→//
1027→// Error Handling Strategy:
1028→//   - Individual file staging errors are logged to stderr but don't fail the operation
1029→//   - This ensures that partial staging succeeds even if some files have issues
1030→//   - If a modified file no longer exists, it's treated as a deletion
1031→//
1032→// The stageCtx parameter is used for user-facing messages to indicate whether
1033→// this is staging for a session checkpoint or a task checkpoint.
1034→func StageFiles(worktree *git.Worktree, modified, newFiles, deleted []string, stageCtx StageFilesContext) {
1035→	// Get repo root for resolving file paths
1036→	// This is critical because fileExists() uses os.Stat() which resolves relative to CWD,
1037→	// but worktree.Add/Remove resolve relative to repo root. If CWD != repo root,
1038→	// fileExists() could return false for existing files, causing worktree.Remove()
1039→	// to incorrectly delete them.
1040→	repoRoot := worktree.Filesystem.Root()
1041→
1042→	// Stage modified files
1043→	for _, file := range modified {
1044→		// Resolve path relative to repo root for existence check
1045→		absPath := filepath.Join(repoRoot, file)
1046→		if fileExists(absPath) {
1047→			if _, err := worktree.Add(file); err != nil {
1048→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
1049→			} else {
1050→				fmt.Fprintf(os.Stderr, "  Staged: %s\n", file)
1051→			}
1052→		} else {
1053→			// File was deleted - stage the deletion
1054→			if _, err := worktree.Remove(file); err != nil {
1055→				fmt.Fprintf(os.Stderr, "  File not found or deleted: %s\n", file)
1056→			}
1057→		}
1058→	}
1059→
1060→	// Stage new files
1061→	if len(newFiles) > 0 {
1062→		fmt.Fprintf(os.Stderr, "Staging %d new files created during %s:\n", len(newFiles), stageCtx)
1063→		for _, file := range newFiles {
1064→			if _, err := worktree.Add(file); err != nil {
1065→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
1066→			} else {
1067→				fmt.Fprintf(os.Stderr, "  Staged new file: %s\n", file)
1068→			}
1069→		}
1070→	}
1071→
1072→	// Stage deleted files
1073→	for _, file := range deleted {
1074→		if _, err := worktree.Remove(file); err != nil {
1075→			fmt.Fprintf(os.Stderr, "  Failed to stage deleted file %s: %v\n", file, err)
1076→		} else {
1077→			fmt.Fprintf(os.Stderr, "  Staged deleted file: %s\n", file)
1078→		}
1079→	}
1080→}
