1171→// ErrBranchNotFound is returned by DeleteBranchCLI when the branch does not exist.
1172→var ErrBranchNotFound = errors.New("branch not found")
1173→
1174→// DeleteBranchCLI deletes a git branch using the git CLI.
1175→// Uses `git branch -D` instead of go-git's RemoveReference because go-git v5
1176→// doesn't properly persist deletions when refs are packed (.git/packed-refs)
1177→// or in a worktree context. This is the same class of go-git v5 bug that
1178→// affects checkout and reset --hard (see HardResetWithProtection).
1179→//
1180→// Returns ErrBranchNotFound if the branch does not exist, allowing callers
1181→// to use errors.Is for idempotent deletion patterns.
1182→func DeleteBranchCLI(branchName string) error {
1183→	ctx := context.Background()
1184→
1185→	// Pre-check: verify the branch exists so callers get a structured error
1186→	// instead of parsing git's output string (which varies across locales).
1187→	// git show-ref exits 1 for "not found" and 128+ for fatal errors (corrupt
1188→	// repo, permissions, not a git directory). Only map exit code 1 to
1189→	// ErrBranchNotFound; propagate other failures as-is.
1190→	check := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName) //nolint:gosec // branchName comes from internal shadow branch naming
1191→	if err := check.Run(); err != nil {
1192→		var exitErr *exec.ExitError
1193→		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
1194→			return fmt.Errorf("%w: %s", ErrBranchNotFound, branchName)
1195→		}
1196→		return fmt.Errorf("failed to check branch %s: %w", branchName, err)
1197→	}
1198→
1199→	cmd := exec.CommandContext(ctx, "git", "branch", "-D", "--", branchName)
1200→	if output, err := cmd.CombinedOutput(); err != nil {
1201→		return fmt.Errorf("failed to delete branch %s: %s: %w", branchName, strings.TrimSpace(string(output)), err)
1202→	}
1203→	return nil
1204→}
1205→
1206→// branchExistsCLI checks if a branch exists using git CLI.
1207→// Returns nil if the branch exists, or an error if it does not.
1208→func branchExistsCLI(branchName string) error {
1209→	ctx := context.Background()
1210→	cmd := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName) //nolint:gosec // branchName comes from internal shadow branch naming
1211→	if err := cmd.Run(); err != nil {
1212→		return fmt.Errorf("branch %s not found: %w", branchName, err)
1213→	}
1214→	return nil
1215→}
1216→
1217→// HardResetWithProtection performs a git reset --hard to the specified commit.
1218→// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
1219→// deletes untracked directories (like .entire/) even when they're in .gitignore.
1220→// Returns the short commit ID (7 chars) on success for display purposes.
1221→func HardResetWithProtection(commitHash plumbing.Hash) (shortID string, err error) {
1222→	ctx := context.Background()
1223→	hashStr := commitHash.String()
1224→	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", hashStr) //nolint:gosec // hashStr is a plumbing.Hash, not user input
1225→	if output, err := cmd.CombinedOutput(); err != nil {
1226→		return "", fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
1227→	}
1228→
1229→	// Return short commit ID for display
1230→	shortID = hashStr
1231→	if len(shortID) > 7 {
1232→		shortID = shortID[:7]
1233→	}
1234→	return shortID, nil
1235→}
1236→
1237→// collectUntrackedFiles collects all untracked files in the working directory.
1238→// This is used to capture the initial state when starting a session,
1239→// ensuring untracked files present at session start are preserved during rewind.
1240→// Excludes protected directories (.git/, .entire/, and agent config directories).
1241→// Works correctly from any subdirectory within the repository.
1242→func collectUntrackedFiles() ([]string, error) {
1243→	// Get repository root to walk from there
1244→	repoRoot, err := GetWorktreePath()
1245→	if err != nil {
1246→		repoRoot = "." // Fallback to current directory
1247→	}
1248→
1249→	var untrackedFiles []string
1250→	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
1251→		if walkErr != nil {
1252→			return nil //nolint:nilerr // Skip filesystem errors during walk
1253→		}
1254→
1255→		// Get path relative to repo root
1256→		relPath, err := filepath.Rel(repoRoot, path)
1257→		if err != nil {
1258→			return nil //nolint:nilerr // Skip paths we can't make relative
1259→		}
1260→
1261→		// Skip directories
1262→		if info.IsDir() {
1263→			if isProtectedPath(relPath) {
1264→				return filepath.SkipDir
1265→			}
1266→			return nil
1267→		}
1268→
1269→		// Skip files in protected directories (shouldn't reach here due to SkipDir, but safety check)
1270→		if isProtectedPath(relPath) {
1271→			return nil
1272→		}
1273→
1274→		untrackedFiles = append(untrackedFiles, relPath)
1275→		return nil
1276→	})
1277→	if err != nil {
1278→		return nil, fmt.Errorf("failed to walk directory: %w", err)
1279→	}
1280→
1281→	return untrackedFiles, nil
1282→}
1283→
1284→// ExtractSessionIDFromCommit extracts the session ID from a commit's trailers.
1285→// It checks the Entire-Session trailer first, then falls back to extracting from
1286→// the metadata directory path in the Entire-Metadata trailer.
1287→// Returns empty string if no session ID is found.
1288→func ExtractSessionIDFromCommit(commit *object.Commit) string {
1289→	// Try Entire-Session trailer first
1290→	if sessionID, found := trailers.ParseSession(commit.Message); found {
1291→		return sessionID
1292→	}
1293→
1294→	// Try extracting from metadata directory (last path component)
1295→	if metadataDir, found := trailers.ParseMetadata(commit.Message); found {
1296→		return filepath.Base(metadataDir)
1297→	}
1298→
1299→	return ""
1300→}
1301→
1302→// NOTE: The following git tree helper functions have been moved to checkpoint/ package:
1303→// - FlattenTree -> checkpoint.FlattenTree
1304→// - CreateBlobFromContent -> checkpoint.CreateBlobFromContent
1305→// - BuildTreeFromEntries -> checkpoint.BuildTreeFromEntries
1306→// - sortTreeEntries (internal to checkpoint package)
1307→// - treeNode, insertIntoTree, buildTreeObject (internal to checkpoint package)
1308→//
1309→// See push_common.go and session_test.go for usage examples.
1310→
1311→// createCommit creates a commit object
1312→func createCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) { //nolint:unparam // already present in codebase
1313→	now := time.Now()
1314→	sig := object.Signature{
1315→		Name:  authorName,
1316→		Email: authorEmail,
1317→		When:  now,
1318→	}
1319→
1320→	commit := &object.Commit{
1321→		TreeHash:  treeHash,
1322→		Author:    sig,
1323→		Committer: sig,
1324→		Message:   message,
1325→	}
1326→
1327→	// Add parent if not a new branch
1328→	if parentHash != plumbing.ZeroHash {
1329→		commit.ParentHashes = []plumbing.Hash{parentHash}
1330→	}
1331→
1332→	obj := repo.Storer.NewEncodedObject()
1333→	if err := commit.Encode(obj); err != nil {
1334→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
1335→	}
1336→
1337→	hash, err := repo.Storer.SetEncodedObject(obj)
1338→	if err != nil {
1339→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
1340→	}
1341→
1342→	return hash, nil
1343→}
1344→
1345→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
1346→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
1347→//
1348→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
1349→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
1350→// the session directory, e.g., auto-commit strategy's sharded metadata), then falls back to
1351→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
1352→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
1353→	// Helper to read first line from a file in tree
1354→	readFirstLine := func(path string) string {
1355→		file, err := tree.File(path)
1356→		if err != nil {
1357→			return ""
1358→		}
1359→		content, err := file.Contents()
1360→		if err != nil {
1361→			return ""
1362→		}
1363→		lines := strings.SplitN(content, "\n", 2)
1364→		if len(lines) > 0 && lines[0] != "" {
1365→			desc := strings.TrimSpace(lines[0])
1366→			// Remove markdown header prefix if present
1367→			return strings.TrimPrefix(desc, "# ")
1368→		}
1369→		return ""
1370→	}
1371→
1372→	// If metadataDir is provided, look there directly
1373→	if metadataDir != "" {
1374→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
1375→			return desc
1376→		}
1377→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
1378→			return desc
1379→		}
1380→		return NoDescription
1381→	}
1382→
1383→	// No metadataDir provided - first try looking at the root of the tree
1384→	// (used when the tree is already the session directory)
1385→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
1386→		return desc
1387→	}
1388→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
1389→		return desc
1390→	}
1391→
1392→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
1393→	// (used when the tree is the full worktree)
1394→	var desc string
1395→	//nolint:errcheck // We ignore errors here as we're just searching for a description
1396→	_ = tree.Files().ForEach(func(f *object.File) error {
1397→		if desc != "" {
1398→			return nil // Already found description
1399→		}
1400→		name := f.Name
1401→		if strings.Contains(name, ".entire/metadata/") {
1402→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
1403→				content, err := f.Contents()
1404→				if err != nil {
1405→					return nil //nolint:nilerr // Skip files we can't read, continue searching
1406→				}
1407→				lines := strings.SplitN(content, "\n", 2)
1408→				if len(lines) > 0 && lines[0] != "" {
1409→					desc = strings.TrimSpace(lines[0])
1410→					desc = strings.TrimPrefix(desc, "# ")
1411→				}
1412→			}
1413→		}
1414→		return nil
1415→	})
1416→
1417→	if desc != "" {
1418→		return desc
1419→	}
1420→	return NoDescription
1421→}
1422→
1423→// GetGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
1424→// It checks local config first, then falls back to global config.
1425→// Returns ("Unknown", "unknown@local") if no user is configured - this allows
1426→// operations to proceed even without git user config, which is especially useful
1427→// for internal metadata commits on branches like entire/checkpoints/v1.
1428→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1429→	// Get repository config (includes local settings)
1430→	cfg, err := repo.Config()
1431→	if err == nil {
1432→		name = cfg.User.Name
1433→		email = cfg.User.Email
1434→	}
1435→
1436→	// If not found in local config, try global config
1437→	if name == "" || email == "" {
1438→		globalCfg, err := config.LoadConfig(config.GlobalScope)
1439→		if err == nil {
1440→			if name == "" {
1441→				name = globalCfg.User.Name
1442→			}
1443→			if email == "" {
1444→				email = globalCfg.User.Email
1445→			}
1446→		}
1447→	}
1448→
1449→	// Provide sensible defaults if git user is not configured
1450→	if name == "" {
1451→		name = "Unknown"
1452→	}
1453→	if email == "" {
1454→		email = "unknown@local"
1455→	}
1456→
1457→	return name, email
1458→}
1459→
1460→// GetCurrentBranchName returns the short name of the current branch if HEAD points to a branch.
1461→// Returns an empty string if in detached HEAD state or if there's an error reading HEAD.
1462→// This is used to capture branch metadata for checkpoints.
1463→func GetCurrentBranchName(repo *git.Repository) string {
1464→	head, err := repo.Head()
1465→	if err != nil || !head.Name().IsBranch() {
1466→		return ""
1467→	}
1468→	return head.Name().Short()
1469→}
1470→
1471→// getMainBranchHash returns the hash of the main branch (main or master).
1472→// Returns ZeroHash if no main branch is found.
1473→func GetMainBranchHash(repo *git.Repository) plumbing.Hash {
1474→	// Try common main branch names
1475→	for _, branchName := range []string{branchMain, branchMaster} {
1476→		// Try local branch first
1477→		ref, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
1478→		if err == nil {
1479→			return ref.Hash()
1480→		}
1481→		// Try remote tracking branch
1482→		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
1483→		if err == nil {
1484→			return ref.Hash()
1485→		}
1486→	}
1487→	return plumbing.ZeroHash
1488→}
1489→
1490→// GetDefaultBranchName returns the name of the default branch.
1491→// First checks origin/HEAD, then falls back to checking if main/master exists.
1492→// Returns empty string if unable to determine.
1493→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
1494→func GetDefaultBranchName(repo *git.Repository) string {
1495→	// Try to get the symbolic reference for origin/HEAD
1496→	// Use resolved=false to get the symbolic ref itself, then extract its target
1497→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), false)
1498→	if err == nil && ref != nil && ref.Type() == plumbing.SymbolicReference {
1499→		target := ref.Target().String()
1500→		if branchName, found := strings.CutPrefix(target, "refs/remotes/origin/"); found {
1501→			return branchName
1502→		}
1503→	}
1504→
1505→	// Fallback: check if origin/main or origin/master exists
1506→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMain), true); err == nil {
1507→		return branchMain
1508→	}
1509→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMaster), true); err == nil {
1510→		return branchMaster
1511→	}
1512→
1513→	// Final fallback: check local branches
1514→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMain), true); err == nil {
1515→		return branchMain
1516→	}
1517→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMaster), true); err == nil {
1518→		return branchMaster
1519→	}
1520→
1521→	return ""
1522→}
1523→
1524→// IsOnDefaultBranch checks if the repository HEAD is on the default branch.
1525→// Returns (isOnDefault, currentBranchName).
1526→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
1527→func IsOnDefaultBranch(repo *git.Repository) (bool, string) {
1528→	currentBranch := GetCurrentBranchName(repo)
1529→	if currentBranch == "" {
1530→		return false, ""
1531→	}
1532→
1533→	defaultBranch := GetDefaultBranchName(repo)
1534→	if defaultBranch == "" {
1535→		// Can't determine default, check common names
1536→		if currentBranch == branchMain || currentBranch == branchMaster {
1537→			return true, currentBranch
1538→		}
1539→		return false, currentBranch
1540→	}
1541→
1542→	return currentBranch == defaultBranch, currentBranch
1543→}
